const TODAY = new Date().toISOString().split("T")[0];

function fmt(val) { const n = parseFloat(val); if (isNaN(n)) return "$0.00"; return "$" + n.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ","); }
function parseCur(val) { return val.replace(/[^0-9.]/g, ""); }

function isLocked(entry) {
  if (!entry?.date) return false;
  const entryDate = new Date(entry.date + "T00:00:00");
  const dayOfWeek = entryDate.getDay();
  const now = new Date();
  let lockDate;
  if (dayOfWeek === 5) lockDate = new Date(entryDate.getTime() + 3 * 86400000);
  else if (dayOfWeek === 6) lockDate = new Date(entryDate.getTime() + 2 * 86400000);
  else lockDate = new Date(entryDate.getTime() + 86400000);
  const lockAt = new Date(lockDate.getFullYear(), lockDate.getMonth(), lockDate.getDate() + 1);
  return now >= lockAt;
}

function fmtDate(s) { return new Date(s + "T12:00:00").toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric", year: "numeric" }); }
function getMonthLabel(d) { return new Date(d + "T12:00:00").toLocaleDateString("en-US", { month: "long", year: "numeric" }); }

// ─── Supabase helpers ───
async function fetchPins() {
  try {
    const { data, error } = await supabase.from("office_pins").select("*");
    if (error) { console.error("Supabase pins error:", error); return {}; }
    const pins = {};
    (data || []).forEach(r => { pins[r.office] = r.pin; });
    return pins;
  } catch (e) { console.error("Pins fetch error:", e); return {}; }
}
async function updatePin(office, newPin) {
  await supabase.from("office_pins").update({ pin: newPin }).eq("office", office);
}
async function fetchEntries() {
  try {
    const { data, error } = await supabase.from("deposits").select("*").order("date", { ascending: false }).order("created_at", { ascending: false });
    if (error) { console.error("Supabase fetch error:", error); return []; }
    return (data || []).map(r => ({
      id: r.id,
      office: r.office || "",
      date: r.date || "",
      deposits: {
        insuranceChecks: String(r.insurance_checks || ""),
        mediEftInsurance: String(r.medi_eft_insurance || ""),
        cash: String(r.cash || ""),
        debitCreditCards: String(r.debit_credit_cards || ""),
        careCredit: String(r.care_credit || ""),
        sunbit: String(r.sunbit || ""),
      },
      grandTotal: parseFloat(r.grand_total || 0),
      pettyCash: String(r.petty_cash || ""),
      initials: String(r.staff_name || ""),
      officeSales: String(r.office_sales || ""),
      uploads: Array.isArray(r.uploads) ? r.uploads : [],
      doctorProd: Array.isArray(r.doctor_prod) ? r.doctor_prod : [],
      patients: (r.patients && typeof r.patients === "object" && !Array.isArray(r.patients)) ? r.patients : {},
      parsedChecks: Array.isArray(r.parsed_checks) ? r.parsed_checks : [],
      savedAt: r.created_at || "",
    }));
  } catch (e) { console.error("Fetch error:", e); return []; }
}
async function saveEntry(entry) {
  try {
    const row = {
    office: entry.office,
    date: entry.date,
    insurance_checks: parseFloat(entry.deposits.insuranceChecks || 0),
    medi_eft_insurance: parseFloat(entry.deposits.mediEftInsurance || 0),
    cash: parseFloat(entry.deposits.cash || 0),
    debit_credit_cards: parseFloat(entry.deposits.debitCreditCards || 0),
    care_credit: parseFloat(entry.deposits.careCredit || 0),
    sunbit: parseFloat(entry.deposits.sunbit || 0),
    grand_total: entry.grandTotal,
    petty_cash: parseFloat(entry.pettyCash || 0),
    staff_name: entry.initials,
    office_sales: parseFloat(entry.officeSales || 0),
    uploads: entry.uploads,
    doctor_prod: entry.doctorProd,
    patients: entry.patients,
    parsed_checks: entry.parsedChecks || [],
  };
  const { data, error } = await supabase.from("deposits").insert(row).select();
  if (error) console.error("Save error:", error);
  return data?.[0];
  } catch (e) { console.error("Save error:", e); return null; }
}
async function deleteEntryDB(id) {
  try {
    const { error } = await supabase.from("deposits").delete().eq("id", id);
    if (error) console.error("Delete error:", error);
  } catch (e) { console.error("Delete error:", e); }
}

// CSV exports
function exportCSV(entries) {
  const h = ["Date","Office",...DEPOSIT_FIELDS.map(f=>f.label),"Grand Total","Petty Cash","Name","Reports"];
  const rows = entries.map(e => [e.date, e.office, ...DEPOSIT_FIELDS.map(f=>e.deposits?.[f.key]||"0"), e.grandTotal||0, e.pettyCash||"0", e.initials||"", Array.isArray(e.uploads)?e.uploads.length:0]);
  dl([h,...rows], `deposit-report-${TODAY}.csv`);
}
function exportDrProdCSV(entries) {
  const h = ["Date","Office","Doctor","Production","Patients","Office Production"];
  const rows = [];
  entries.forEach(e => {
    (e.doctorProd || []).forEach(dp => { rows.push([e.date, e.office, dp.name, dp.production||"0", dp.patients||"0", e.officeSales||"0"]); });
    if (!(e.doctorProd?.length)) rows.push([e.date, e.office, "", "", "", e.officeSales||"0"]);
  });
  dl([h,...rows], `production-report-${TODAY}.csv`);
}
function exportPatientCSV(entries) {
  const h = ["Date","Office",...PATIENT_FIELDS.map(f=>f.label)];
  const rows = entries.map(e => [e.date, e.office, ...PATIENT_FIELDS.map(f=>e.patients?.[f.key]||"0")]);
  dl([h,...rows], `patient-report-${TODAY}.csv`);
}
function dl(data, filename) {
  const csv = data.map(r => r.map(c => `"${c}"`).join(",")).join("\n");
  const b = new Blob([csv], { type: "text/csv" }); const u = URL.createObjectURL(b);
  const a = document.createElement("a"); a.href = u; a.download = filename; a.click(); URL.revokeObjectURL(u);
}

// ─── PDF Parsing ───
let pdfjsLoaded = false;
async function loadPdfJs() {
  if (pdfjsLoaded) return;
  if (!window.pdfjsLib) {
    await new Promise((resolve, reject) => {
      const s = document.createElement("script");
      s.src = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js";
      s.onload = resolve; s.onerror = reject;
      document.head.appendChild(s);
    });
  }
  window.pdfjsLib.GlobalWorkerOptions.workerSrc = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";
  pdfjsLoaded = true;
}
async function extractPdfText(file) {
  await loadPdfJs();
  const buf = await file.arrayBuffer();
  const pdf = await window.pdfjsLib.getDocument({ data: buf }).promise;
  let text = "";
  for (let i = 1; i <= pdf.numPages; i++) {
    const page = await pdf.getPage(i);
    const content = await page.getTextContent();
    text += content.items.map(item => item.str).join(" ") + "\n";
  }
  return text;
}
function parseDailyPayments(text) {
  const t = text.replace(/\s+/g, " ");
  const result = {};
  const checksSection = t.match(/Insurance Checks.*?(?=Insurance EFTs)/i);
  if (checksSection) {
    const amounts = checksSection[0].match(/[\d,]+\.\d{2}/g);
    if (amounts && amounts.length > 0) {
      const last = amounts[amounts.length - 1].replace(/,/g, "");
      result.insuranceChecks = parseFloat(last).toFixed(2);
    }
  }
  const findTotal = (pattern) => { const m = t.match(pattern); if (m) { const val = m[1].replace(/[,$]/g, ""); return isNaN(parseFloat(val)) ? "" : parseFloat(val).toFixed(2); } return ""; };
  result.mediEftInsurance = findTotal(/Total Insurance Payments[:\s]*\$?([\d,]+\.\d{2})/i);
  const cashSection = t.match(/Patient Payments.*?Cash.*?(?=Credit Card)/is);
  if (cashSection) { const a = cashSection[0].match(/[\d,]+\.\d{2}/g); if (a?.length) result.cash = parseFloat(a[a.length-1].replace(/,/g,"")).toFixed(2); }
  const ccSection = t.match(/Credit Card.*?(?=SunBit|Sunbit)/is);
  if (ccSection) { const a = ccSection[0].match(/[\d,]+\.\d{2}/g); if (a?.length) result.debitCreditCards = parseFloat(a[a.length-1].replace(/,/g,"")).toFixed(2); }
  const sunbitSection = t.match(/Sun[Bb]it.*?(?=CareCredit|Care Credit)/is);
  if (sunbitSection) { const a = sunbitSection[0].match(/[\d,]+\.\d{2}/g); if (a?.length) result.sunbit = parseFloat(a[a.length-1].replace(/,/g,"")).toFixed(2); }
  const ccreditSection = t.match(/Care\s?Credit.*?(?=Adit|Total Patient|$)/is);
  if (ccreditSection) { const a = ccreditSection[0].match(/[\d,]+\.\d{2}/g); if (a?.length) result.careCredit = parseFloat(a[a.length-1].replace(/,/g,"")).toFixed(2); }

  result.checks = [];
  if (checksSection) {
    const section = checksSection[0];
    const dateChunks = section.split(/(?=\d{2}\/\d{2}\/\d{4})/);
    dateChunks.forEach(chunk => {
      const dateMatch = chunk.match(/^(\d{2}\/\d{2}\/\d{4})/);
      if (!dateMatch) return;
      const amounts = chunk.match(/-?[\d,]+\.\d{2}/g);
      if (!amounts || amounts.length === 0) return;
      const amount = amounts[amounts.length - 1].replace(/,/g, "");
      const rest = chunk.replace(dateMatch[0], "").trim();
      const withoutAmt = rest.replace(/-?[\d,]+\.\d{2}$/, "").trim();
      const words = withoutAmt.split(/\s+/);
      let checkNum = "";
      for (let i = words.length - 1; i >= 0; i--) {
        const w = words[i];
        if (/\d/.test(w) || /^[A-Z]{2,}/.test(w)) {
          if (i > 0 && /^[A-Z]{2,}$/.test(words[i-1])) checkNum = words[i-1] + " " + w;
          else checkNum = w;
          break;
        }
      }
      const parts = withoutAmt.split(/\s{2,}|\t/);
      let patientName = parts.length >= 2 ? parts[1]?.trim() || "" : "";
      result.checks.push({ date: dateMatch[1], checkNum: checkNum || "N/A", amount: parseFloat(amount).toFixed(2), patient: patientName, raw: chunk.trim() });
    });
  }
  const hasValues = Object.values(result).some(v => { if (Array.isArray(v)) return v.length > 0; return v && v !== "0.00"; });
  return hasValues ? result : null;
}

// ─── Doctor Production Editor ───
function DoctorProdEditor({ doctorProd, setDoctorProd, officeSales, setOfficeSales }) {
  const selected = doctorProd.map(d => d.name);
  const toggleDoc = (name) => {
    if (selected.includes(name)) setDoctorProd(prev => prev.filter(d => d.name !== name));
    else setDoctorProd(prev => [...prev, { name, production: "", patients: "" }]);
  };
  const updateDoc = (name, field, val) => { setDoctorProd(prev => prev.map(d => d.name === name ? { ...d, [field]: parseCur(val) } : d)); };
  const totalPatients = doctorProd.reduce((s, d) => s + (parseInt(d.patients) || 0), 0);
  return (
    <div style={S.section}>
      <h2 style={S.sectionTitle}>Production</h2>
      <div style={{ marginBottom: 16 }}>
        <label style={S.label}>Select Doctors Working Today</label>
        <div style={S.docChipGrid}>
          {DOCTORS.map(name => (<button key={name} style={{ ...S.docChip, ...(selected.includes(name) ? S.docChipActive : {}) }} onClick={() => toggleDoc(name)}>{name}</button>))}
        </div>
      </div>
      {doctorProd.length > 0 && (
        <div style={S.docEntries}>
          {doctorProd.map(d => (
            <div key={d.name} style={S.docEntryCard}>
              <div style={S.docEntryName}>{d.name}</div>
              <div style={S.docEntryFields}>
                <div style={S.docField}><label style={S.docFieldLabel}>Production</label><div style={S.currencyWrap}><span style={S.dollarSign}>$</span><input type="text" inputMode="decimal" placeholder="0.00" style={S.currencyInput} value={d.production} onChange={e => updateDoc(d.name, "production", e.target.value)} /></div></div>
                <div style={S.docField}><label style={S.docFieldLabel}>Patients</label><input type="text" inputMode="numeric" placeholder="0" style={S.docPatientsInput} value={d.patients} onChange={e => updateDoc(d.name, "patients", e.target.value.replace(/[^0-9]/g, ""))} /></div>
              </div>
            </div>
          ))}
          <div style={S.docTotalRow}><span style={S.docTotalLabel}>Total Patients</span><span style={S.docTotalValue}>{totalPatients}</span></div>
        </div>
      )}
      <div style={{ marginTop: doctorProd.length > 0 ? 16 : 0, paddingTop: doctorProd.length > 0 ? 16 : 0, borderTop: doctorProd.length > 0 ? "1px solid #E4EEF2" : "none" }}>
        <label style={S.label}>Office Production</label>
        <div style={{marginTop:8,...S.currencyWrap}}><span style={S.dollarSign}>$</span><input type="text" inputMode="decimal" placeholder="0.00" style={S.currencyInput} value={officeSales} onChange={e => setOfficeSales(parseCur(e.target.value))} /></div>
      </div>
    </div>
  );
}

// ─── PIN Screen ───
function PinScreen({ onUnlock }) {
  const [mode, setMode] = useState("office");
  const [selectedOffice, setSelectedOffice] = useState("");
  const [pin, setPin] = useState("");
  const [error, setError] = useState("");
  const [shake, setShake] = useState(false);
  const [loading, setLoading] = useState(false);
  const doShake = () => { setShake(true); setTimeout(() => setShake(false), 500); };
  const handleSubmit = async () => {
    if (mode === "master") { if (pin === MASTER_PIN) onUnlock({ master: true }); else { setError("Incorrect PIN"); setPin(""); doShake(); } return; }
    if (!selectedOffice) { setError("Select your office"); return; }
    setLoading(true);
    const pins = await fetchPins();
    setLoading(false);
    const office = OFFICES.find(o => o.name === selectedOffice);
    if (office && pin === pins[office.name]) onUnlock(office); else { setError("Incorrect PIN"); setPin(""); doShake(); }
  };
  const brand = OFFICES.find(o => o.name === selectedOffice)?.brand;
  return (
    <div style={S.pinContainer}>
      <div style={{ ...S.pinCard, animation: shake ? "shake 0.4s ease" : "none" }}>
        <style>{`@keyframes shake{0%,100%{transform:translateX(0)}20%,60%{transform:translateX(-8px)}40%,80%{transform:translateX(8px)}}`}</style>
        <div style={S.pinLogoWrap}><img src={mode==="master"||brand!=="fundamental"?ARTICO_LOGO:FUND_LOGO} alt="Logo" style={S.pinLogo}/></div>
        <h2 style={S.pinTitle}>Daily Deposit Form</h2>
        <div style={S.pinToggle}>
          <button style={{...S.pinToggleBtn,...(mode==="office"?S.pinToggleActive:{})}} onClick={()=>{setMode("office");setPin("");setError("");}}>Office Login</button>
          <button style={{...S.pinToggleBtn,...(mode==="master"?S.pinToggleActive:{})}} onClick={()=>{setMode("master");setPin("");setError("");}}>Owner / Reports</button>
        </div>
        {mode==="office"&&(<div style={S.pinFieldGroup}><label style={S.pinLabel}>Office</label><select style={S.pinSelect} value={selectedOffice} onChange={e=>{setSelectedOffice(e.target.value);setError("");}}>
          <option value="">— Select Office —</option>{OFFICES.map(o=><option key={o.name} value={o.name}>{o.name}</option>)}</select></div>)}
        {mode==="master"&&<p style={S.pinSubtitle}>Enter the owner PIN to access reports and export data for all offices.</p>}
        <div style={S.pinFieldGroup}><label style={S.pinLabel}>PIN</label><input type="password" inputMode="numeric" maxLength={8} placeholder="••••••" style={S.pinInput}
          value={pin} onChange={e=>{setPin(e.target.value);setError("");}} onKeyDown={e=>e.key==="Enter"&&handleSubmit()}/></div>
        {error&&<div style={S.pinError}>{error}</div>}
        <button style={S.pinBtn} onClick={handleSubmit} disabled={loading}>{loading?"Checking...":"Unlock"}</button>
      </div>
    </div>
  );
}

// ─── Owner Reports Dashboard ───
function ReportsDashboard({ onLogout }) {
  const [ownerTab, setOwnerTab] = useState("dashboard");
  const [filterOffice, setFilterOffice] = useState("all");
  const [filterMonth, setFilterMonth] = useState("all");
  const [pins, setPins] = useState({});
  const [editingPin, setEditingPin] = useState(null);
  const [newPin, setNewPin] = useState("");
  const [pinMsg, setPinMsg] = useState("");
  const [prodFilterDoc, setProdFilterDoc] = useState("all");
  const [entries, setEntries] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => { loadData(); }, []);
  const loadData = async () => {
    setLoading(true);
    const [e, p] = await Promise.all([fetchEntries(), fetchPins()]);
    setEntries(e); setPins(p); setLoading(false);
  };

  const handlePinSave = async (n) => { if(newPin.length<4){setPinMsg("PIN must be at least 4 digits");return;} await updatePin(n,newPin); setPins(p=>({...p,[n]:newPin})); setEditingPin(null);setNewPin("");setPinMsg(`PIN updated for ${n}`);setTimeout(()=>setPinMsg(""),3000);};
  const handlePinReset = async (n) => { const d=OFFICES.find(o=>o.name===n)?.defaultPin||"0000"; await updatePin(n,d); setPins(p=>({...p,[n]:d})); setEditingPin(null);setNewPin("");setPinMsg(`PIN reset for ${n}`);setTimeout(()=>setPinMsg(""),3000);};

  const months = [...new Set(entries.map(e=>e.date?.slice(0,7)).filter(Boolean))].sort().reverse();
  const filtered = entries.filter(e => {
    if (filterOffice!=="all"&&e.office!==filterOffice) return false;
    if (filterMonth!=="all"&&!e.date?.startsWith(filterMonth)) return false;
    return true;
  });

  const totals = {}; DEPOSIT_FIELDS.forEach(f=>{totals[f.key]=0;}); let grandSum=0; let pettySum=0;
  filtered.forEach(e => { DEPOSIT_FIELDS.forEach(f=>{totals[f.key]+=parseFloat(e.deposits?.[f.key]||0);}); grandSum+=parseFloat(e.grandTotal||0); pettySum+=parseFloat(e.pettyCash||0); });
  const officeBreakdown = {};
  OFFICES.forEach(o => { const oe=filtered.filter(e=>e.office===o.name); if(!oe.length)return; let gt=0; oe.forEach(e=>{gt+=parseFloat(e.grandTotal||0);}); officeBreakdown[o.name]={count:oe.length,total:gt}; });

  const drTotals = {}; let totalOfficeSales=0; let totalAllProd=0; let totalAllPatients=0;
  filtered.forEach(e => {
    totalOfficeSales += parseFloat(e.officeSales || 0);
    (e.doctorProd || []).forEach(dp => {
      if (!drTotals[dp.name]) drTotals[dp.name] = { production: 0, patients: 0, days: 0 };
      drTotals[dp.name].production += parseFloat(dp.production || 0);
      drTotals[dp.name].patients += parseInt(dp.patients || 0);
      drTotals[dp.name].days += 1;
      totalAllProd += parseFloat(dp.production || 0);
      totalAllPatients += parseInt(dp.patients || 0);
    });
  });
  const prodFiltered = prodFilterDoc === "all" ? filtered : filtered.filter(e => (e.doctorProd||[]).some(d=>d.name===prodFilterDoc));

  const patientTotals = {}; PATIENT_FIELDS.forEach(f => { patientTotals[f.key] = 0; });
  filtered.forEach(e => { PATIENT_FIELDS.forEach(f => { patientTotals[f.key] += parseInt(e.patients?.[f.key] || 0); }); });
  const patientByOffice = {};
  OFFICES.forEach(o => {
    const oe = filtered.filter(e => e.office === o.name); if (!oe.length) return;
    const t = {}; PATIENT_FIELDS.forEach(f => { t[f.key] = 0; });
    oe.forEach(e => { PATIENT_FIELDS.forEach(f => { t[f.key] += parseInt(e.patients?.[f.key] || 0); }); });
    patientByOffice[o.name] = { ...t, count: oe.length };
  });

  if (loading) return <div style={S.container}><div style={{padding:60,textAlign:"center",color:"#5A7A8A"}}>Loading data...</div></div>;

  return (
    <div style={S.container}>
      <div style={{...S.header,background:"linear-gradient(135deg,#1a1a2e 0%,#16213e 60%,#0f3460 100%)"}}>
        <div style={S.headerTop}>
          <div style={S.logoWrap}><img src={ARTICO_LOGO} alt="Artico" style={S.logoImg}/></div>
          <div><button style={S.logoutBtn} onClick={onLogout}>Sign Out ↗</button><button style={{...S.logoutBtn,marginLeft:8}} onClick={loadData}>↻ Refresh</button></div>
        </div>
        <div style={S.headerMeta}><span style={{...S.officeBadge,background:"rgba(255,200,50,0.2)",color:"#ffd666"}}>👑 Owner</span><span style={S.h1}>Reports &amp; Export</span></div>
        <div style={S.tabBar}>
          <button style={{...S.tab,...(ownerTab==="dashboard"?S.tabActive:{})}} onClick={()=>setOwnerTab("dashboard")}>Dashboard</button>
          <button style={{...S.tab,...(ownerTab==="patients"?S.tabActive:{})}} onClick={()=>setOwnerTab("patients")}>Patients</button>
          <button style={{...S.tab,...(ownerTab==="drprod"?S.tabActive:{})}} onClick={()=>setOwnerTab("drprod")}>Production</button>
          <button style={{...S.tab,...(ownerTab==="settings"?S.tabActive:{})}} onClick={()=>setOwnerTab("settings")}>Settings</button>
        </div>
      </div>

      {ownerTab==="patients"&&(
        <div style={S.formWrap}>
          <div style={S.topRow}><div style={S.fieldGroup}><label style={S.label}>Office</label><select style={S.select} value={filterOffice} onChange={e=>setFilterOffice(e.target.value)}><option value="all">All Offices</option>{OFFICES.map(o=><option key={o.name} value={o.name}>{o.name}</option>)}</select></div>
            <div style={S.fieldGroup}><label style={S.label}>Month</label><select style={S.select} value={filterMonth} onChange={e=>setFilterMonth(e.target.value)}><option value="all">All Time</option>{months.map(m=><option key={m} value={m}>{getMonthLabel(m+"-15")}</option>)}</select></div></div>
          <div style={S.patientGrid}><div style={S.patientCardMain}><div style={S.summaryLabel}>Total Patients</div><div style={{fontSize:32,fontWeight:800,color:"#0B3D5C"}}>{patientTotals.totalPatients}</div><div style={{fontSize:12,color:"#8AA4B0",marginTop:4}}>{filtered.length} entries</div></div>
            <div style={S.patientCardsRow}>{PATIENT_FIELDS.filter(f=>f.key!=="totalPatients").map(f=>(<div key={f.key} style={S.patientCard}><div style={S.patientCardLabel}>{f.label}</div><div style={S.patientCardValue}>{patientTotals[f.key]}</div></div>))}</div></div>
          {filterOffice==="all"&&Object.keys(patientByOffice).length>0&&(<div style={S.section}><h2 style={S.sectionTitle}>By Office</h2>{OFFICES.map(o=>{const d=patientByOffice[o.name];if(!d)return null;const pct=patientTotals.totalPatients>0?(d.totalPatients/patientTotals.totalPatients)*100:0;return(<div key={o.name} style={S.reportRow}><div style={{flex:1}}><div style={S.reportLabel}>{o.name}</div><div style={S.barTrack}><div style={{...S.barFill,width:`${Math.min(pct,100)}%`,background:o.brand==="fundamental"?"#38a0b8":"#1A6B8A"}}/></div><div style={{fontSize:11,color:"#8AA4B0",marginTop:2}}>{d.count} days · {d.newPatients} new · {d.selfPay} self pay · {d.insurance} ins · {d.fdh} FDH</div></div><div style={{...S.reportValue,fontSize:17}}>{d.totalPatients}</div></div>);})}</div>)}
          <div style={S.section}><h2 style={S.sectionTitle}>Export Patient Data</h2><p style={{fontSize:13,color:"#6A8A9A",margin:"0 0 14px",lineHeight:1.5}}>Download CSV with patient data for current filters.</p><button style={S.exportBtn} onClick={()=>exportPatientCSV(filtered)}>⬇ Download CSV ({filtered.length} entries)</button></div>
        </div>
      )}

      {ownerTab==="settings"&&(
        <div style={S.formWrap}><div style={S.section}><h2 style={S.sectionTitle}>Office PIN Management</h2><p style={{fontSize:13,color:"#6A8A9A",margin:"0 0 16px",lineHeight:1.5}}>Change or reset the login PIN for any office.</p>
          {pinMsg&&<div style={S.pinSuccessMsg}>{pinMsg}</div>}
          {OFFICES.map(o=>(<div key={o.name} style={S.pinCard2}><div style={S.pinCard2Header}><div style={S.pinCard2Info}><div style={S.pinCard2Name}>{o.name}</div><div style={S.pinCard2Current}>Current PIN: <span style={S.pinCard2Dots}>{pins[o.name]?.replace(/./g,"•")}</span></div></div>
            {editingPin!==o.name&&<button style={S.pinChangeBtn} onClick={()=>{setEditingPin(o.name);setNewPin("");}}>Change PIN</button>}</div>
            {editingPin===o.name&&(<div style={S.pinEditArea}><label style={S.pinEditLabel}>New PIN</label><input type="text" inputMode="numeric" maxLength={8} placeholder="Enter new PIN" style={S.pinEditInput} value={newPin} onChange={e=>setNewPin(e.target.value.replace(/[^0-9]/g,""))}/>
              <div style={S.pinEditActions}><button style={S.pinSaveBtn} onClick={()=>handlePinSave(o.name)}>Save PIN</button><button style={S.pinResetBtn} onClick={()=>handlePinReset(o.name)}>Reset Default</button><button style={S.pinCancelBtn} onClick={()=>{setEditingPin(null);setNewPin("");}}>Cancel</button></div></div>)}
          </div>))}
        </div></div>
      )}

      {ownerTab==="drprod"&&(
        <div style={S.formWrap}>
          <div style={S.topRow}><div style={S.fieldGroup}><label style={S.label}>Office</label><select style={S.select} value={filterOffice} onChange={e=>setFilterOffice(e.target.value)}><option value="all">All Offices</option>{OFFICES.map(o=><option key={o.name} value={o.name}>{o.name}</option>)}</select></div>
            <div style={S.fieldGroup}><label style={S.label}>Month</label><select style={S.select} value={filterMonth} onChange={e=>setFilterMonth(e.target.value)}><option value="all">All Time</option>{months.map(m=><option key={m} value={m}>{getMonthLabel(m+"-15")}</option>)}</select></div>
            <div style={S.fieldGroup}><label style={S.label}>Doctor</label><select style={S.select} value={prodFilterDoc} onChange={e=>setProdFilterDoc(e.target.value)}><option value="all">All Doctors</option>{DOCTORS.map(d=><option key={d} value={d}>{d}</option>)}</select></div></div>
          <div style={S.summaryRow}><div style={S.summaryCard}><div style={S.summaryLabel}>Doctor Production</div><div style={S.summaryValue}>{fmt(totalAllProd)}</div></div>
            <div style={S.summaryCard}><div style={S.summaryLabel}>Total Patients</div><div style={{...S.summaryValue,color:"#1A6B8A"}}>{totalAllPatients}</div></div>
            <div style={S.summaryCard}><div style={S.summaryLabel}>Office Production</div><div style={{...S.summaryValue,fontSize:20}}>{fmt(totalOfficeSales)}</div></div></div>
          <div style={{...S.totalRow,marginBottom:0}}><span style={S.totalLabel}>TOTAL OFFICE PRODUCTION</span><span style={S.totalValue}>{fmt(totalAllProd + totalOfficeSales)}</span></div>
          <div style={S.section}><h2 style={S.sectionTitle}>By Doctor</h2>{Object.keys(drTotals).length===0?<p style={{fontSize:13,color:"#8AA4B0"}}>No production data for this filter.</p>:
            Object.entries(drTotals).sort((a,b)=>b[1].production-a[1].production).map(([name, d]) => {if(prodFilterDoc!=="all"&&name!==prodFilterDoc)return null;const pct=totalAllProd>0?(d.production/totalAllProd)*100:0;return(<div key={name} style={S.reportRow}><div style={{flex:1}}><div style={S.reportLabel}>{name}</div><div style={S.barTrack}><div style={{...S.barFill,width:`${Math.min(pct,100)}%`}}/></div><div style={{fontSize:11,color:"#8AA4B0",marginTop:2}}>{d.patients} patients · {d.days} days</div></div><div style={S.reportValue}>{fmt(d.production)}</div></div>);})}</div>
          <div style={S.section}><h2 style={S.sectionTitle}>Export Production Data</h2><p style={{fontSize:13,color:"#6A8A9A",margin:"0 0 14px",lineHeight:1.5}}>Download CSV with production data for current filters.</p><button style={S.exportBtn} onClick={()=>exportDrProdCSV(prodFiltered)}>⬇ Download CSV ({prodFiltered.length} entries)</button></div>
        </div>
      )}

      {ownerTab==="dashboard"&&(
        <div style={S.formWrap}>
          <div style={S.topRow}><div style={S.fieldGroup}><label style={S.label}>Office</label><select style={S.select} value={filterOffice} onChange={e=>setFilterOffice(e.target.value)}><option value="all">All Offices</option>{OFFICES.map(o=><option key={o.name} value={o.name}>{o.name}</option>)}</select></div>
            <div style={S.fieldGroup}><label style={S.label}>Month</label><select style={S.select} value={filterMonth} onChange={e=>setFilterMonth(e.target.value)}><option value="all">All Time</option>{months.map(m=><option key={m} value={m}>{getMonthLabel(m+"-15")}</option>)}</select></div></div>
          <div style={S.summaryRow}><div style={S.summaryCard}><div style={S.summaryLabel}>Grand Total</div><div style={S.summaryValue}>{fmt(grandSum)}</div><div style={S.summaryMeta}>{filtered.length} entries</div></div>
            <div style={S.summaryCard}><div style={S.summaryLabel}>Petty Cash</div><div style={{...S.summaryValue,fontSize:20}}>{fmt(pettySum)}</div></div></div>
          <div style={S.section}><h2 style={S.sectionTitle}>By Category</h2>{DEPOSIT_FIELDS.map(f=>{const pct=grandSum>0?(totals[f.key]/grandSum)*100:0;return(<div key={f.key} style={S.reportRow}><div style={{flex:1}}><div style={S.reportLabel}>{f.label}</div><div style={S.barTrack}><div style={{...S.barFill,width:`${Math.min(pct,100)}%`}}/></div></div><div style={S.reportValue}>{fmt(totals[f.key])}</div></div>);})}</div>
          {filterOffice==="all"&&Object.keys(officeBreakdown).length>0&&(<div style={S.section}><h2 style={S.sectionTitle}>By Office</h2>{OFFICES.map(o=>{const d=officeBreakdown[o.name];if(!d)return null;const pct=grandSum>0?(d.total/grandSum)*100:0;return(<div key={o.name} style={S.reportRow}><div style={{flex:1}}><div style={S.reportLabel}>{o.name}</div><div style={S.barTrack}><div style={{...S.barFill,width:`${Math.min(pct,100)}%`,background:o.brand==="fundamental"?"#38a0b8":"#1A6B8A"}}/></div><div style={{fontSize:11,color:"#8AA4B0",marginTop:2}}>{d.count} entries</div></div><div style={S.reportValue}>{fmt(d.total)}</div></div>);})}</div>)}
          <div style={S.section}><h2 style={S.sectionTitle}>Export Data</h2><p style={{fontSize:13,color:"#6A8A9A",margin:"0 0 14px",lineHeight:1.5}}>Download CSV of {filtered.length} entries with current filters.</p><button style={S.exportBtn} onClick={()=>exportCSV(filtered)}>⬇ Download CSV ({filtered.length} entries)</button></div>
          <div style={S.section}><h2 style={S.sectionTitle}>Entries ({filtered.length})</h2><div style={{overflowX:"auto"}}><table style={S.table}><thead><tr><th style={S.th}>Date</th><th style={S.th}>Office</th>{DEPOSIT_FIELDS.map(f=><th key={f.key} style={S.th}>{f.label}</th>)}<th style={S.th}>Total</th></tr></thead><tbody>
            {filtered.slice(0,50).map(e=><tr key={e.id}><td style={S.td}>{e.date}</td><td style={S.td}>{e.office?.replace("Artico Dental ","").replace("Fundamental ","Fund. ")}</td>{DEPOSIT_FIELDS.map(f=><td key={f.key} style={{...S.td,textAlign:"right"}}>{fmt(e.deposits?.[f.key]||0)}</td>)}<td style={{...S.td,textAlign:"right",fontWeight:700}}>{fmt(e.grandTotal)}</td></tr>)}
          </tbody></table>{filtered.length>50&&<p style={{fontSize:12,color:"#8AA4B0",textAlign:"center",marginTop:8}}>Showing first 50. Download CSV for full data.</p>}</div></div>
        </div>
      )}
    </div>
  );
}

// ─── Main App ───
export default function DailyDepositApp() {
  const [auth, setAuth] = useState(null);
  const handleLogout = () => { setAuth(null); };
  if (!auth) return <PinScreen onUnlock={setAuth} />;
  if (auth.master) return <ReportsDashboard onLogout={handleLogout} />;
  return <OfficeView auth={auth} onLogout={handleLogout} />;
}

// ─── Office View ───
function OfficeView({ auth, onLogout }) {
  const [view, setView] = useState("form");
  const [selectedDate, setSelectedDate] = useState(TODAY);
  const [deposits, setDeposits] = useState({});
  const [pettyCash, setPettyCash] = useState("");
  const [initials, setInitials] = useState("");
  const [uploads, setUploads] = useState([]);
  const [doctorProd, setDoctorProd] = useState([]);
  const [officeSales, setOfficeSales] = useState("");
  const [patients, setPatients] = useState({});
  const [parsedChecks, setParsedChecks] = useState([]);
  const [checkedChecks, setCheckedChecks] = useState({});
  const [savedEntries, setSavedEntries] = useState([]);
  const [saveFlash, setSaveFlash] = useState(false);
  const [parseStatus, setParseStatus] = useState("");
  const [expandedEntry, setExpandedEntry] = useState(null);
  const [unlockedEntries, setUnlockedEntries] = useState({});
  const [unlockPinPrompt, setUnlockPinPrompt] = useState(null);
  const [unlockPinValue, setUnlockPinValue] = useState("");
  const [unlockPinError, setUnlockPinError] = useState("");
  const [loading, setLoading] = useState(true);
  const fileRef = useRef(null);

  const officeName = auth.name;
  const isArtico = auth.brand === "artico";
  const logoSrc = isArtico ? ARTICO_LOGO : FUND_LOGO;
  const headerBg = isArtico ? "linear-gradient(135deg,#0B3D5C 0%,#1A6B8A 60%,#2A8CB0 100%)" : "linear-gradient(135deg,#1a3a4a 0%,#2a6a7a 60%,#38a0b8 100%)";
  const grandTotal = DEPOSIT_FIELDS.reduce((s,f)=>s+(parseFloat(deposits[f.key]||0)||0),0);

  const loadOfficeEntries = async () => {
    setLoading(true);
    const all = await fetchEntries();
    setSavedEntries(all.filter(e => e.office === officeName));
    setLoading(false);
  };
  useEffect(() => { loadOfficeEntries(); }, []);

  const handleLogout = () => { handleClear(); setSelectedDate(TODAY); setView("form"); setSavedEntries([]); onLogout(); };

  const handleSave = async () => {
    const entry = { office: officeName, date: selectedDate, deposits:{...deposits}, grandTotal, pettyCash, initials, uploads:[...uploads], doctorProd:[...doctorProd], officeSales, patients:{...patients}, parsedChecks:[...parsedChecks] };
    setLoading(true);
    await saveEntry(entry);
    await loadOfficeEntries();
    setLoading(false);
    setSaveFlash(true); setTimeout(()=>setSaveFlash(false),2000);
  };

  const handleClear = () => { setDeposits({}); setPettyCash(""); setInitials(""); setUploads([]); setDoctorProd([]); setOfficeSales(""); setPatients({}); setParsedChecks([]); setCheckedChecks({}); };

  const handleFileUpload = async (files) => {
    const fl = Array.from(files).map(f => ({ name: f.name, size: (f.size / 1024).toFixed(1) + " KB" }));
    setUploads(p => [...p, ...fl]);
    const pdfFile = Array.from(files).find(f => f.type === "application/pdf" || f.name.endsWith(".pdf"));
    if (pdfFile) {
      setParseStatus("parsing");
      try {
        const text = await extractPdfText(pdfFile);
        const parsed = parseDailyPayments(text);
        if (parsed) {
          setDeposits(prev => ({ ...prev, insuranceChecks: parsed.insuranceChecks||prev.insuranceChecks||"", mediEftInsurance: parsed.mediEftInsurance||prev.mediEftInsurance||"", cash: parsed.cash||prev.cash||"", debitCreditCards: parsed.debitCreditCards||prev.debitCreditCards||"", careCredit: parsed.careCredit||prev.careCredit||"", sunbit: parsed.sunbit||prev.sunbit||"" }));
          if (parsed.checks?.length > 0) { setParsedChecks(parsed.checks); setCheckedChecks({}); }
          setParseStatus("success"); setTimeout(() => setParseStatus(""), 4000);
        } else { setParseStatus("error"); setTimeout(() => setParseStatus(""), 4000); }
      } catch (e) { console.error("PDF parse error:", e); setParseStatus("error"); setTimeout(() => setParseStatus(""), 4000); }
    }
  };

  const loadEntry = (entry) => {
    if(isLocked(entry)&&!unlockedEntries[entry.id]) return;
    setSelectedDate(entry.date); setDeposits(entry.deposits||{}); setPettyCash(entry.pettyCash||""); setInitials(entry.initials||"");
    setUploads(entry.uploads||[]); setDoctorProd(entry.doctorProd||[]); setOfficeSales(entry.officeSales||""); setPatients(entry.patients||{}); setParsedChecks(entry.parsedChecks||[]); setCheckedChecks({}); setView("form");
  };
  const handleDelete = async (id) => {
    const e = savedEntries.find(x=>x.id===id);
    if(e&&isLocked(e)&&!unlockedEntries[id]) return;
    setLoading(true);
    await deleteEntryDB(id);
    await loadOfficeEntries();
    setLoading(false);
  };

  return (
    <div style={S.container}>
      <div style={{...S.header,background:headerBg}}>
        <div style={S.headerTop}><div style={S.logoWrap}><img src={logoSrc} alt={officeName} style={S.logoImg}/></div><button style={S.logoutBtn} onClick={handleLogout}>Switch Office ↗</button></div>
        <div style={S.headerMeta}><span style={S.officeBadge}>{officeName}</span><span style={S.h1}>Daily Deposit Form</span></div>
        <div style={S.tabBar}>
          <button style={{...S.tab,...(view==="form"?S.tabActive:{})}} onClick={()=>setView("form")}>New Entry</button>
          <button style={{...S.tab,...(view==="history"?S.tabActive:{})}} onClick={()=>{setView("history");loadOfficeEntries();}}>History ({savedEntries.length})</button>
        </div>
      </div>

      {view==="form"?(
        <div style={S.formWrap}>
          <div style={S.fieldGroup}><label style={S.label}>Date</label><input type="date" style={S.dateInput} value={selectedDate} onChange={e=>setSelectedDate(e.target.value)}/></div>

          <div style={S.section}><h2 style={S.sectionTitle}>Daily Report PDF</h2>
            <p style={S.uploadHint}>Upload the daily report PDF to auto-fill deposit amounts below.</p>
            <div style={S.dropZone} onClick={()=>fileRef.current?.click()} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();handleFileUpload(e.dataTransfer.files);}}>
              <input ref={fileRef} type="file" accept=".pdf" multiple style={{display:"none"}} onChange={e=>handleFileUpload(e.target.files)}/><span style={S.dropIcon}>📄</span><span style={S.dropText}>Click or drop PDF report</span>
            </div>
            {parseStatus==="parsing"&&<div style={S.parseMsg}>⏳ Reading PDF and filling in deposit amounts...</div>}
            {parseStatus==="success"&&<div style={S.parseSuccess}>✅ Deposit amounts auto-filled from PDF. Please review below.</div>}
            {parseStatus==="error"&&<div style={S.parseError}>⚠️ Could not read amounts from PDF. Please enter manually.</div>}
            {uploads.map((f,i)=>(<div key={i} style={S.fileChip}><span style={S.fileName}>📄 {f.name}</span><span style={S.fileSize}>{f.size}</span><button style={S.fileRemove} onClick={()=>setUploads(p=>p.filter((_,j)=>j!==i))}>×</button></div>))}
          </div>

          <div style={S.section}><h2 style={S.sectionTitle}>Deposit Amounts</h2>
            {DEPOSIT_FIELDS.map(f=>(<div key={f.key} style={S.depositRow}><label style={S.depositLabel}>{f.label}</label><div style={S.currencyWrap}><span style={S.dollarSign}>$</span><input type="text" inputMode="decimal" placeholder="0.00" style={S.currencyInput} value={deposits[f.key]||""} onChange={e=>setDeposits(p=>({...p,[f.key]:parseCur(e.target.value)}))}/></div></div>))}
            <div style={S.totalRow}><span style={S.totalLabel}>GRAND TOTAL</span><span style={S.totalValue}>{fmt(grandTotal)}</span></div>
          </div>

          <div style={S.metaRow}>
            <div style={S.fieldGroup}><label style={S.label}>Petty Cash</label><div style={S.currencyWrap}><span style={S.dollarSign}>$</span><input type="text" inputMode="decimal" placeholder="0.00" style={S.currencyInput} value={pettyCash} onChange={e=>setPettyCash(parseCur(e.target.value))}/></div></div>
            <div style={S.fieldGroup}><label style={S.label}>Name</label><input type="text" placeholder="Full Name" style={S.nameInput} value={initials} onChange={e=>setInitials(e.target.value)}/></div>
          </div>

          <DoctorProdEditor doctorProd={doctorProd} setDoctorProd={setDoctorProd} officeSales={officeSales} setOfficeSales={setOfficeSales} />

          <div style={S.section}><h2 style={S.sectionTitle}>Patients</h2>
            {PATIENT_FIELDS.map(f=>(<div key={f.key} style={S.depositRow}><label style={S.depositLabel}>{f.label}</label><div style={S.patientInputWrap}><input type="text" inputMode="numeric" placeholder="0" style={S.patientInputField} value={patients[f.key]||""} onChange={e=>setPatients(p=>({...p,[f.key]:e.target.value.replace(/[^0-9]/g,"")}))}/></div></div>))}
          </div>

          {parsedChecks.length > 0 && (
            <div style={S.section}>
              <h2 style={S.sectionTitle}>Check Verification</h2>
              <div style={S.checkSummaryBar}><span>{Object.keys(checkedChecks).length} of {parsedChecks.length} verified</span><span style={{fontWeight:800}}>{parsedChecks.length-Object.keys(checkedChecks).length===0?"✅ All matched":`${parsedChecks.length-Object.keys(checkedChecks).length} remaining`}</span></div>
              <div style={S.checkList}>{parsedChecks.map((ck,i)=>{const v=!!checkedChecks[i];return(<div key={i} style={{...S.checkItem,...(v?S.checkItemVerified:S.checkItemUnverified)}} onClick={()=>setCheckedChecks(p=>{const n={...p};if(n[i])delete n[i];else n[i]=true;return n;})}>
                <div style={S.checkCheckbox}>{v?<span style={{color:"#27AE60",fontSize:18}}>✓</span>:<span style={{color:"#C8DDE6",fontSize:18}}>○</span>}</div>
                <div style={S.checkInfo}><div style={S.checkNum}>Check# {ck.checkNum}</div>{ck.patient&&<div style={S.checkPatient}>{ck.patient}</div>}</div>
                <div style={S.checkAmount}>{fmt(ck.amount)}</div></div>);})}</div>
              <div style={S.checkTotalBar}><span style={S.checkTotalLabel}>Total ({parsedChecks.length} checks)</span><span style={S.checkTotalValue}>{fmt(parsedChecks.reduce((s,c)=>s+parseFloat(c.amount||0),0))}</span></div>
            </div>
          )}

          <div style={S.actions}><button style={S.clearBtn} onClick={handleClear}>Clear Form</button><button style={{...S.saveBtn,...(saveFlash?S.saveBtnFlash:{}),opacity:loading?0.6:1}} onClick={handleSave} disabled={loading}>{loading?"Saving...":saveFlash?"✓ Saved!":"Save Entry"}</button></div>
        </div>
      ):(
        <div style={S.historyWrap}>
          {loading&&<div style={{padding:20,textAlign:"center",color:"#5A7A8A"}}>Loading...</div>}
          {!loading&&savedEntries.length===0?(<div style={S.emptyState}><span style={{fontSize:40}}>📋</span><p style={S.emptyText}>No entries yet for {officeName}</p></div>):(
            <div style={S.entriesList}>{savedEntries.map(entry=>{const lk=isLocked(entry)&&!unlockedEntries[entry.id];return(
              <div key={entry.id} style={S.entryCard}>
                <div style={S.entryHeader} onClick={()=>setExpandedEntry(expandedEntry===entry.id?null:entry.id)}>
                  <div style={{flex:1}}><div style={S.entryDate}>{fmtDate(entry.date)}</div><span style={lk?S.lockedBadge:S.editableBadge}>{lk?"🔒 Locked":"✏️ Editable"}</span></div>
                  <div style={S.entryRight}><div style={S.entryTotal}>{fmt(entry.grandTotal)}</div><span style={S.expandArrow}>{expandedEntry===entry.id?"▲":"▼"}</span></div>
                </div>
                {expandedEntry===entry.id&&(
                  <div style={S.entryDetails}>
                    {DEPOSIT_FIELDS.map(f=>(<div key={f.key} style={S.detailRow}><span style={S.detailLabel}>{f.label}</span><span style={S.detailValue}>{fmt(entry.deposits?.[f.key]||0)}</span></div>))}
                    <div style={S.detailDivider}/>
                    <div style={S.detailRow}><span style={S.detailLabel}>Petty Cash</span><span style={S.detailValue}>{fmt(entry.pettyCash||0)}</span></div>
                    <div style={S.detailRow}><span style={S.detailLabel}>Name</span><span style={S.detailValue}>{entry.initials||"—"}</span></div>
                    {(entry.doctorProd||[]).length>0&&(<><div style={S.detailDivider}/><div style={{...S.detailLabel,fontWeight:600,marginBottom:4}}>Production:</div>
                      {entry.doctorProd.map((d,i)=>(<div key={i} style={S.detailRow}><span style={S.detailLabel}>{d.name}</span><span style={S.detailValue}>{fmt(d.production)} · {d.patients||0} pts</span></div>))}
                      <div style={S.detailRow}><span style={S.detailLabel}>Office Production</span><span style={S.detailValue}>{fmt(entry.officeSales||0)}</span></div></>)}
                    {entry.patients&&Object.values(entry.patients).some(v=>v)&&(<><div style={S.detailDivider}/><div style={{...S.detailLabel,fontWeight:600,marginBottom:4}}>Patients:</div>
                      {PATIENT_FIELDS.map(f=>(<div key={f.key} style={S.detailRow}><span style={S.detailLabel}>{f.label}</span><span style={S.detailValue}>{entry.patients[f.key]||0}</span></div>))}</>)}
                    {!lk&&<div style={S.entryActions}><button style={S.loadBtn} onClick={()=>loadEntry(entry)}>Edit Entry</button><button style={S.deleteBtn} onClick={()=>handleDelete(entry.id)}>Delete</button>
                      {unlockedEntries[entry.id]&&<button style={{...S.pinChangeBtn,fontSize:12,padding:"8px 14px",minWidth:0}} onClick={()=>{setUnlockedEntries(p=>{const n={...p};delete n[entry.id];return n;});}}>🔒 Lock</button>}</div>}
                    {lk&&(<div><div style={S.lockedMsg}>This entry is locked.</div>
                      {unlockPinPrompt===entry.id?(<div style={{marginTop:10,display:"flex",gap:8,alignItems:"center"}}>
                        <input type="password" inputMode="numeric" maxLength={8} placeholder="Owner PIN" style={{...S.dateInput,flex:1,textAlign:"center",letterSpacing:4,fontWeight:700}} value={unlockPinValue} onChange={e=>{setUnlockPinValue(e.target.value);setUnlockPinError("");}} onKeyDown={e=>{if(e.key==="Enter"){if(unlockPinValue===MASTER_PIN){setUnlockedEntries(p=>({...p,[entry.id]:true}));setUnlockPinPrompt(null);setUnlockPinValue("");}else{setUnlockPinError("Wrong PIN");setUnlockPinValue("");}}}}/>
                        <button style={{...S.pinSaveBtn,flex:"none",padding:"10px 16px"}} onClick={()=>{if(unlockPinValue===MASTER_PIN){setUnlockedEntries(p=>({...p,[entry.id]:true}));setUnlockPinPrompt(null);setUnlockPinValue("");}else{setUnlockPinError("Wrong PIN");setUnlockPinValue("");}}}>Unlock</button>
                        <button style={{...S.pinCancelBtn,flex:"none",padding:"10px 14px"}} onClick={()=>{setUnlockPinPrompt(null);setUnlockPinValue("");setUnlockPinError("");}}>Cancel</button></div>
                      ):(<button style={{...S.loadBtn,marginTop:10,display:"block",textAlign:"center"}} onClick={()=>{setUnlockPinPrompt(entry.id);setUnlockPinValue("");setUnlockPinError("");}}>🔓 Unlock with Owner PIN</button>)}
                      {unlockPinError&&unlockPinPrompt===entry.id&&<div style={{color:"#C0392B",fontSize:12,fontWeight:600,marginTop:6,textAlign:"center"}}>{unlockPinError}</div>}
                    </div>)}
                  </div>
                )}
              </div>
            );})}</div>
          )}
        </div>
      )}
    </div>
  );
}

